import{_ as i,l as r,o as a,c as n,v as l,p as d,x as o,d as c,i as C,S as E}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"NCCL 调优","description":"","frontmatter":{"title":"NCCL 调优","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/nccl-tuning.md","filePath":"llm/nccl-tuning.md","lastUpdated":1789023840000}'),s={name:"llm/nccl-tuning.md"};function p(A,e,L,N,_,h){const t=r("Mermaid");return a(),n("div",null,[e[1]||(e[1]=l('<h1 id="nccl-调优" tabindex="-1">NCCL 调优 <a class="header-anchor" href="#nccl-调优" aria-label="Permalink to &quot;NCCL 调优&quot;">​</a></h1><div class="epigraph"><p>集合通信库按拓扑选环或树、按体积切块；推理的小消息若仍走训练默认，启动开销会把 TP 的短 All-Reduce 变成逐步主项。</p><footer>—— NVIDIA NCCL 用户指南中的算法、协议与拓扑探测；训练侧大块梯度与推理短激活要分开调</footer></div><p><a href="/llm/tp-comm-overlap">上一课</a>假设通信原语已经够快，才谈得上重叠。本课写仍走 NCCL 时的旋钮：算法（Ring/Tree）、协议（LL/LL128/Simple）、通道数、缓冲。自定义 AR 覆盖不了的跨节点、大 prefill、以及 MoE 的 all-to-all，还得靠 NCCL。后课 MoE 批处理会再碰到 all-to-all；这里先把稠密 TP 的 All-Reduce 调完。不把环形算法的推导再写一遍，那是下一课程「通信与集群」的主干。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NCCL 默认面向训练：大块、延迟可被计算藏住。推理 decode 的 All-Reduce 体积小、频率等于层数×token。默认 Simple 协议带宽好、延迟差；LL 协议延迟好、大块带宽差。缺口是按消息体积分派协议，并固定拓扑探测结果，避免每次建组都重新扫 NVLink。<code>NCCL_P2P_LEVEL</code>、<code>NCCL_IB_DISABLE</code>、网卡绑定在多节点上决定你以为的 NVLink 域是否其实绕了 PCI 或 NIC。</p><p>错误 NUMA / GPU-NIC 亲和会让「调了 LL 仍然慢」。先确认拓扑，再改算法字符串。</p><p><span class="marginnote">CUDA Graph 与 NCCL 的兼容随版本变：捕获期间禁止的操作、是否支持用户缓冲，要以当前 NCCL 文档为准，不要抄两年前进程的环境变量表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对目标消息大小做微基准：All-Reduce 延迟 vs bytes。decode 点落在延迟平台，应试 LL/LL128；prefill 点落在带宽斜坡，用 Simple。通道数过多会把小消息切得更碎。固定 <code>NCCL_ALGO</code> / <code>NCCL_PROTO</code> 做 A/B，但只在已验证拓扑上。与自定义 AR 分派：体积小于阈值走自定义，否则 NCCL——阈值由这张微基准定，不要写死 1MB 当宇宙常数。</p><p>环境变量在进程启动时读。与<a href="/llm/kernel-autotuning">内核自动调优</a>一样，按 SKU 与节点形状存一份已知好的配置，不要每容器靠默认。</p>',10)),(a(),d(E,null,{default:o(()=>[C(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOPO%5B%22%E7%A1%AE%E8%AE%A4%20NVLink%20%2F%20NIC%20%E6%8B%93%E6%89%91%22%5D%20--%3E%20BENCH%5B%22All-Reduce%20%E5%BB%B6%E8%BF%9F-%E4%BD%93%E7%A7%AF%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20BENCH%20--%3E%20DEC%5B%22decode%3A%20%E4%BD%8E%E5%BB%B6%E8%BF%9F%E5%8D%8F%E8%AE%AE%22%5D%0A%20%20BENCH%20--%3E%20PRE%5B%22prefill%3A%20%E5%B8%A6%E5%AE%BD%E5%8D%8F%E8%AE%AE%22%5D%0A%20%20BENCH%20--%3E%20SPLIT%5B%22%E9%98%88%E5%80%BC%3A%20%E8%87%AA%E5%AE%9A%E4%B9%89%20AR%20vs%20NCCL%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Ring 的延迟随 rank 数线性，Tree 的延迟随层数对数；小规模 NVLink 域两者都可能被启动开销淹没。调优改的是常数项与切块，不改集合通信的渐近。重叠课要求通信走单独流：NCCL 默认流与计算流的同步点要显式，否则调了协议也看不到重叠。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要在生产用 <code>NCCL_DEBUG=INFO</code> 常开。不要把单机 TP=8 的配置拷到跨节点 TP=8。安全：环境变量属于部署契约，应进版本控制。下一课：MoE 推理里专家 token 的批怎么凑。</p><p>出处：NVIDIA NCCL 文档。算法课序见后续 Ring/Tree 专文。不发明 arXiv。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>decode 小 All-Reduce 要低延迟协议；大块用带宽协议。</li><li>先拓扑与亲和，再改 <code>ALGO</code>/<code>PROTO</code>。</li><li>用延迟-体积曲线定自定义 AR 的阈值。</li><li>CUDA Graph 兼容性随 NCCL 版本变。</li><li>配置按 SKU 固化，不要靠默认。</li><li>下一课：MoE 推理批处理。</li><li>出处：NVIDIA NCCL 用户指南。</li></ul>',7))])}const u=i(s,[["render",p]]);export{m as __pageData,u as default};
